  115: {"summary":"Moscovium is the name of a synthetic superheavy element in the periodic table that has the symbol Mc and has the atomic number 115. It is an extremely radioactive element; its most stable known isotope, moscovium-289, has a half-life of only 220 milliseconds. It is also known as eka-bismuth or simply element 115.","description":null,"occurrence":"Made by bombarding americium-243 with calcium-48.","usesDetail":null,"uses":"no practical uses; superheavy research only","nameOrigin":"Moscow region, Russia","appearance":null,"discoveryNote":"Calcium-48 on americium-243; named after the Moscow region.","isotopes":[{"mass":287,"exactMass":287.19082,"abundance":0,"halfLife":"37 ms","halfLifeSec":0.037,"halfLifeHuman":"37 ms","stable":false,"decay":"A","decayPct":100,"decay2":"SF","spin":null},{"mass":288,"exactMass":288.192879,"abundance":0,"halfLife":"0.17 s","halfLifeSec":0.17,"halfLifeHuman":"170 ms","stable":false,"decay":"A","decayPct":100,"spin":null},{"mass":289,"exactMass":289.193971,"abundance":0,"halfLife":"296 ms","halfLifeSec":0.296,"halfLifeHuman":"296 ms","stable":false,"decay":"A","decayPct":100,"decay2":"SF","spin":null},{"mass":290,"exactMass":290.196235,"abundance":0,"halfLife":"0.65 s","halfLifeSec":0.65,"halfLifeHuman":"650 ms","stable":false,"decay":"A","decayPct":100,"decay2":"SF","spin":null}],"ionicRadii":[],"allotropes":[],"supply":null,"namedBy":null,"bioNote":"No role."},
  116: {"summary":"Livermorium is a synthetic superheavy element with symbol Lv and atomic number 116. It is an extremely radioactive element that has only been created in the laboratory and has not been observed in nature. The element is named after the Lawrence Livermore National Laboratory in the United States, which collaborated with the Joint Institute for Nuclear Research in Dubna, Russia to discover livermorium in 2000.","description":null,"occurrence":"Made by bombardng curium-248 with calcium-48.","usesDetail":null,"uses":"no practical uses; superheavy research only","nameOrigin":"Livermore, California","appearance":null,"discoveryNote":"Calcium-48 on curium-248; named after Livermore.","isotopes":[{"mass":290,"exactMass":290.198635,"abundance":0,"halfLife":"8.3 ms","halfLifeSec":0.0083,"halfLifeHuman":"8.3 ms","stable":false,"decay":"A","decayPct":100,"decay2":"SF","spin":"0+"},{"mass":291,"exactMass":291.201014,"abundance":0,"halfLife":"19 ms","halfLifeSec":0.019,"halfLifeHuman":"19 ms","stable":false,"decay":"A","decayPct":100,"decay2":"SF","spin":null},{"mass":292,"exactMass":292.201969,"abundance":0,"halfLife":"12.8 ms","halfLifeSec":0.0128,"halfLifeHuman":"12.8 ms","stable":false,"decay":"A","decayPct":100,"decay2":"SF","spin":"0+"},{"mass":293,"exactMass":293.204583,"abundance":0,"halfLife":"95 ms","halfLifeSec":0.095,"halfLifeHuman":"95 ms","stable":false,"decay":"A","decayPct":100,"decay2":"SF","spin":null},{"mass":294,"exactMass":null,"abundance":0,"halfLife":null,"halfLifeSec":null,"stable":false,"decay":null,"spin":"0+"}],"ionicRadii":[],"allotropes":[],"supply":null,"namedBy":null,"bioNote":"No role."},
  117: {"summary":"Tennessine is a superheavy artificial chemical element with an atomic number of 117 and a symbol of Ts. Also known as eka-astatine or element 117, it is the second-heaviest known element and penultimate element of the 7th period of the periodic table. As of 2016, fifteen tennessine atoms have been observed: six when it was first synthesized in 2010, seven in 2012, and two in 2014.","description":null,"occurrence":"Made by bombarding berkelium-249 with calcium-48.","usesDetail":null,"uses":"no practical uses; superheavy research only","nameOrigin":"Tennessee, USA","appearance":null,"discoveryNote":"Calcium-48 on berkelium-249 made at Oak Ridge; named after Tennessee.","isotopes":[{"mass":293,"exactMass":293.208727,"abundance":0,"halfLife":"21 ms","halfLifeSec":0.021,"halfLifeHuman":"21 ms","stable":false,"decay":"A","decayPct":100,"decay2":"SF","spin":null},{"mass":294,"exactMass":294.21084,"abundance":0,"halfLife":"51 ms","halfLifeSec":0.051,"halfLifeHuman":"51 ms","stable":false,"decay":"A","decayPct":100,"spin":null}],"ionicRadii":[],"allotropes":[],"supply":null,"namedBy":null,"bioNote":"No role."},
  118: {"summary":"Oganesson is IUPAC's name for the transactinide element with the atomic number 118 and element symbol Og. It is also known as eka-radon or element 118, and on the periodic table of the elements it is a p-block element and the last one of the 7th period. Oganesson is currently the only synthetic member of group 18.","description":null,"occurrence":"Made by bombarding californium-249 with calcium-48.","usesDetail":null,"uses":"no practical uses; superheavy research only","nameOrigin":"Yuri Oganessian","appearance":null,"discoveryNote":"Calcium-48 on californium-249 (announced 2006); named for Yuri Oganessian — the heaviest known element.","isotopes":[{"mass":294,"exactMass":294.213979,"abundance":0,"halfLife":"0.58 ms","halfLifeSec":0.00058,"halfLifeHuman":"580 µs","stable":false,"decay":"A","decayPct":100,"decay2":"SF","spin":"0+"}],"ionicRadii":[],"allotropes":[],"supply":null,"namedBy":null,"bioNote":"No role."}
